from __future__ import annotations

import json
import base64
from typing import Any

import httpx

from igchat_v2._core._utils import formAll, post_form_json_async

_URL = "https://www.instagram.com/api/graphql/"
_DOC_ID = 25498450883167126


def _build_form(
    dataIGS: dict[str, Any], postID: str, typePost: str = "my_post"
) -> dict[str, Any]:
    if not str(postID).strip():
        raise ValueError("ID bài viết không được để trống.")
    """
        my_post = những bài viết của chính bản thân bạn viết nên (không phải share)
        others = phần còn lại, những bài viết của người khác, hoặc bài viết share từ người khác
    """
    if typePost == "my_post":
        postID_Params = f"S:_I1054626957723036:{postID}"
    else:
        postID_Params = f"S:_I{dataIGS['IGSID']}:{postID}:{postID}"
    PostID_Base64 = base64.b64encode(postID_Params.encode()).decode()
    data_form = formAll(dataIGS, "useCometArchivePostMutation", _DOC_ID)
    data_form["variables"] = json.dumps(
        {
            "input": {
                "story_id": PostID_Base64,
                "story_location": "TIMELINE",
                "surface": "POST_CHEVRON_MENU_TIMELINE",
                "actor_id": dataIGS["IGSID"],
                "client_mutation_id": "1",
            }
        },
        separators=(",", ":"),
    )

    return data_form


def _parse_result(payload: dict[str, Any]) -> dict[str, Any]:
    if payload.get("status") == "ok" and not payload.get("errors"):
        return {"success": 1, "messages": "Lưu trữ bài viết thành công!"}
    errors = payload.get("errors") or []
    message = (
        errors[0].get("message") if errors and isinstance(errors[0], dict) else None
    )
    try:
        status = payload["data"]["archive_story"]["success"]
    except (KeyError, TypeError):
        status = False
    if errors or not status:
        return {
            "error": 1,
            "messages": message or "Instagram không phản hồi hợp lệ.",
        }
    return {"success": 1, "messages": "Lưu trữ bài viết thành công!"}


async def func(
    dataIGS: dict[str, Any],
    postID: str,
    typePost: str = "my_post",
    client: httpx.AsyncClient | None = None,
) -> dict[str, Any]:
    payload = await post_form_json_async(
        _URL,
        _build_form(dataIGS, postID, typePost),
        dataIGS["cookieIGS"],
        client=client,
    )
    return _parse_result(payload)


async def save_instagram_media(
    dataIGS: dict[str, Any],
    post_or_url: str | int,
    *,
    unsave: bool = False,
    client: httpx.AsyncClient | None = None,
) -> dict[str, Any]:
    """Lưu (Save) hoặc bỏ lưu (Unsave) bài viết / Reel Instagram vào bộ sưu tập cá nhân."""
    from igchat_v2._features._instagram._reactionPost import shortcode_to_media_id

    try:
        media_id = shortcode_to_media_id(post_or_url)
        action = "unsave" if unsave else "save"
        payload = await post_form_json_async(
            f"https://www.instagram.com/api/v1/web/save/{media_id}/{action}/",
            {},
            dataIGS["cookieIGS"],
            client=client,
        )
        if payload.get("status") == "ok":
            return {
                "success": 1,
                "mediaId": media_id,
                "messages": (
                    "Đã bỏ lưu bài viết!" if unsave else "Đã lưu bài viết vào bộ sưu tập!"
                ),
            }
        return {
            "error": 1,
            "messages": str(
                payload.get("message") or "Instagram từ chối thao tác lưu bài viết."
            ),
        }
    except (httpx.HTTPError, ValueError, TypeError, KeyError) as exc:
        return {"error": 1, "messages": str(exc)}

